struct RbQtrChannel { int (*leer)(); uint32_t minimo, maximo; };
static RbQtrChannel linea_canales[16];
static int linea_count = 0;
static float linea_ultima = 0;
inline void linea_agregar(int (*leer)(), const char* bloque) {
    if (linea_count == 16) { rb_fail(bloque, "Maximo 16 canales QTR"); return; }
    linea_canales[linea_count++] = {leer, {ADC_MAX}, 0};
}
inline bool linea_lista(const char* bloque) {
    if (linea_count) return true; rb_fail(bloque, "Agrega los canales del sensor de linea al iniciar"); return false;
}
inline void linea_calibrar(const char* bloque) {
    if (!linea_lista(bloque)) return;
    for (int i = 0; i < linea_count; i++) { uint32_t v = linea_canales[i].leer(); if (v < linea_canales[i].minimo) linea_canales[i].minimo = v; if (v > linea_canales[i].maximo) linea_canales[i].maximo = v; }
}
inline float linea_nivel(int i, const String& color) {
    const RbQtrChannel& c = linea_canales[i];
    float minimo = c.minimo, maximo = c.maximo;
    if (maximo - minimo < 50) { minimo = 0; maximo = {ADC_MAX}; }
    float nivel = fmaxf(0, fminf(100, (c.leer() - minimo) * 100 / (maximo - minimo)));
    return color == "negra" ? nivel : 100 - nivel;
}
inline float linea_posicion(const String& color, const char* bloque) {
    if (!linea_lista(bloque)) return 0;
    float total = 0, suma = 0;
    for (int i = 0; i < linea_count; i++) { float n = linea_nivel(i, color); if (n > 10) { total += n; suma += n * (linea_count == 1 ? 0 : i * 200.0f / (linea_count - 1) - 100); } }
    if (total == 0) return linea_ultima < 0 ? -100 : 100;
    if (linea_count == 1) return 0;
    linea_ultima = suma / total; return roundf(linea_ultima * 10) / 10;
}
inline float linea_canal(float numero, const String& color, const char* bloque) {
    if (!linea_lista(bloque)) return 0;
    if (numero < 1 || numero > linea_count) { rb_fail(bloque, "Canal QTR fuera de rango"); return 0; }
    return roundf(linea_nivel(int(numero) - 1, color) * 10) / 10;
}
inline bool linea_detectada(const String& color, const char* bloque) {
    if (!linea_lista(bloque)) return false;
    bool found = false; for (int i = 0; i < linea_count; i++) if (linea_nivel(i, color) > 50) found = true; return found;
