linea_canales = []
linea_ultima = 0
def linea_crudo(bloque):
    if not linea_canales:
        rb_fail(bloque, "Agrega los canales del sensor de línea al iniciar")
    return [rb_adc_read(canal[0], bloque) for canal in linea_canales]
def linea_niveles(color, bloque):
    # 0 = sin línea, 100 = línea. Las QTR analógicas dan más voltaje sobre negro.
    niveles = []
    for canal, valor in zip(linea_canales, linea_crudo(bloque)):
        minimo, maximo = canal[1], canal[2]
        if maximo - minimo < 50:
            minimo, maximo = 0, 4095
        nivel = max(0, min(100, (valor - minimo) * 100 / (maximo - minimo)))
        niveles.append(nivel if color == "negra" else 100 - nivel)
    return niveles
def linea_posicion(color, bloque):
    # -100 bajo el canal 1, 0 al centro, 100 bajo el último canal.
    global linea_ultima
    niveles = linea_niveles(color, bloque)
    total = sum(nivel for nivel in niveles if nivel > 10)
    if total == 0:
        return -100 if linea_ultima < 0 else 100
    if len(niveles) == 1:
        return 0
    paso = 200 / (len(niveles) - 1)
    suma = sum(nivel * (i * paso - 100) for i, nivel in enumerate(niveles) if nivel > 10)
    linea_ultima = suma / total
    return round(linea_ultima, 1)

